#!/bin/sh
# ORBIT TEMP bootstrap 1.0.4-b1 - generated by make_bootstrap.py, do not edit. Its SHA-256 is pinned by the install command copied from the admin panel.
# Downloads the signed ORBIT TEMP installer 1.0.4, checks SHA-256 AND the usign (Ed25519) signature, and only then starts it.
# Usage: sh /tmp/ob.sh [auto|github|mirror]     auto = GitHub first, the mirror when GitHub fails or does not verify (both files always from ONE source)
# Writes only /tmp/orbit-install.sh, .sig and .pub; on ANY failure these are removed and nothing on the router is changed. The activation key is asked by the installer.
INSTALLER=/tmp/orbit-install.sh
SIG=/tmp/orbit-install.sh.sig
PUB=/tmp/orbit-install.pub
SHA256='3d018d837cde23dce644d6c31b00fd53b17bc5f1a1fe550cf9b82ac3b8f5202b'
GH='https://raw.githubusercontent.com/wester11/voikop/db9b2c654360feaca130fa0917468ab973171733/orbit-temp/v1.0.4/orbit-temp-install.sh'
MI='https://orbit2.netvoid.ru/dl/orbit-temp/1.0.4/orbit-temp-install.sh'
M=${1:-auto}

fail() {
  rm -f "$INSTALLER" "$SIG" "$PUB"
  echo "ORBIT-TEMP: $1 - installer removed, nothing was changed" >&2
  exit 1
}
case "$M" in
  auto|github|mirror) ;;
  *) echo "usage: sh /tmp/ob.sh [auto|github|mirror]" >&2; exit 2 ;;
esac
for t in wget sha256sum usign; do
  command -v "$t" >/dev/null 2>&1 || fail "required tool '$t' not found"
done

# download both files from ONE url base, then verify; returns non-zero on any problem (nothing is trusted before verify passes)
get() {
  rm -f "$INSTALLER" "$SIG" "$PUB"
  wget -q -T 20 -O "$INSTALLER" "$1" && wget -q -T 20 -O "$SIG" "$1.sig" &&
    printf '%s\n' 'untrusted comment: ORBIT-TEMP installer signing key 2026-11' 'RWQwd436XR7+J3D8sygjIOeoPrSeKJD8zpKOa5Bv+zTkkd7ANp+KzkF8' > "$PUB" &&
    echo "$SHA256  $INSTALLER" | sha256sum -c - >/dev/null 2>&1 &&
    usign -V -m "$INSTALLER" -p "$PUB" >/dev/null 2>&1
}

case "$M" in
  github) get "$GH" || fail "download or verification from GitHub failed" ;;
  mirror) get "$MI" || fail "download or verification from the mirror failed" ;;
  auto)
    if ! get "$GH"; then
      echo "ORBIT-TEMP: GitHub not reachable or not verifiable, using the mirror" >&2
      get "$MI" || fail "download or verification failed (GitHub and mirror)"
    fi ;;
esac
echo "ORBIT-TEMP: installer 1.0.4 verified (SHA-256 + usign signature), starting it"
exec sh "$INSTALLER"
